package com.skyclone.mod.collections;

import com.google.gson.Gson;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Every collection, its tiers and rewards, as loaded from {@code data/collections/collections.json}
 * (generated by {@code tools/gen/collections/gen_collections.py} from the research data).
 *
 * <p>Pure Java (Gson only, no Bukkit) so unit tests can load the shipping file and check it.
 */
public final class CollectionCatalog {

    // ---- JSON shape ---------------------------------------------------------------------------

    public static final class Category {
        public String id;
        public String name;
        public String icon;
        public int slot;
    }

    /** One reward line of a tier. {@code type} decides which fields are set. */
    public static final class Reward {
        /** recipe, minion, skillxp, discount, stat, skillcap, pet, book, potion, loot, text */
        public String type;
        public String label;
        public String item;       // recipe / loot: item id (may be null when unresolvable)
        public String prefix;     // minion: "WHEAT_GENERATOR" (tier n = prefix + "_" + n)
        public String skill;      // skillxp / skillcap
        public String enchant;    // discount / book
        public String stat;       // stat
        public String pet;        // pet type id
        public String potion;     // potion id
        public String level;      // book: roman level
        public long amount;       // skillxp / stat / skillcap
        public int percent;       // discount
        public boolean forge;     // recipe made at the forge
    }

    public static final class Tier {
        public int tier;
        public long amount;
        public int sbxp;
        public List<Reward> rewards = new ArrayList<>();
    }

    /** Boss collections: progress comes from boss kills, matched by tokens in the mob id. */
    public static final class Boss {
        public List<String> match = new ArrayList<>();
        public int masterWeight = 2;
        public Map<String, Integer> tierWeights = new LinkedHashMap<>();
    }

    public static final class Coll {
        public String id;
        public String category;
        public String name;
        public String icon;
        public String skull;
        /** Other item ids that count toward this collection, with how many units each is worth. */
        public Map<String, Integer> aliases = new LinkedHashMap<>();
        public List<Tier> tiers = new ArrayList<>();
        public Boss boss;

        public int maxTier() { return tiers.size(); }
        public boolean isBoss() { return boss != null; }

        /** Tier n (1-based) or null. */
        public Tier tier(int n) { return n >= 1 && n <= tiers.size() ? tiers.get(n - 1) : null; }
    }

    static final class Doc {
        List<Category> categories = new ArrayList<>();
        List<Coll> collections = new ArrayList<>();
    }

    /** An item id resolved to the collection it feeds and how many units one item is worth. */
    public record Feed(Coll coll, int weight) {}

    // ---- index ----------------------------------------------------------------------------------

    private final List<Category> categories;
    private final Map<String, Coll> byId = new LinkedHashMap<>();
    private final Map<String, Feed> byItem = new HashMap<>();
    private final Map<String, Coll> byKey = new HashMap<>();
    private final Map<String, List<Coll>> byCategory = new LinkedHashMap<>();
    private int totalTiers;

    private CollectionCatalog(Doc doc) {
        this.categories = List.copyOf(doc.categories);
        for (Category c : categories) byCategory.put(c.id, new ArrayList<>());
        for (Coll c : doc.collections) {
            if (c.id == null || c.tiers == null || c.tiers.isEmpty()) continue;
            if (c.aliases == null) c.aliases = new LinkedHashMap<>();
            c.tiers.sort((a, b) -> Integer.compare(a.tier, b.tier));
            byId.put(c.id, c);
            byCategory.computeIfAbsent(c.category, k -> new ArrayList<>()).add(c);
            byKey.put(norm(c.id), c);
            byKey.putIfAbsent(norm(c.name), c);
            if (c.isBoss()) {
                // BOSS_BONZO is also reachable as BONZO and by its floor token (F1)
                byKey.putIfAbsent(norm(c.id.substring("BOSS_".length())), c);
                for (String t : c.boss.match) byKey.putIfAbsent(norm(t), c);
            } else {
                totalTiers += c.tiers.size();
                byItem.put(c.id, new Feed(c, 1));
                c.aliases.forEach((item, w) -> {
                    byItem.putIfAbsent(item, new Feed(c, Math.max(1, w)));
                    byKey.putIfAbsent(norm(item), c);
                });
            }
        }
    }

    public static CollectionCatalog parse(Reader r) {
        Doc doc = new Gson().fromJson(r, Doc.class);
        if (doc == null) doc = new Doc();
        return new CollectionCatalog(doc);
    }

    public static CollectionCatalog parse(InputStream in) {
        return parse(new InputStreamReader(in, StandardCharsets.UTF_8));
    }

    public static CollectionCatalog empty() { return new CollectionCatalog(new Doc()); }

    static String norm(String s) {
        return s == null ? "" : s.trim().toUpperCase(Locale.ROOT).replace(' ', '_').replace('-', '_');
    }

    // ---- queries --------------------------------------------------------------------------------

    public List<Category> categories() { return categories; }

    public Category category(String id) {
        for (Category c : categories) if (c.id.equalsIgnoreCase(id) || c.name.equalsIgnoreCase(id)) return c;
        return null;
    }

    public Collection<Coll> all() { return Collections.unmodifiableCollection(byId.values()); }

    public List<Coll> inCategory(String categoryId) { return byCategory.getOrDefault(categoryId, List.of()); }

    /** Exact collection id ("WHEAT", "INK_SACK:3", "BOSS_BONZO"). */
    public Coll get(String id) { return id == null ? null : byId.get(id); }

    /** Which collection (and weight) an item id feeds; null if none. Boss collections are never fed by items. */
    public Feed feed(String itemId) { return itemId == null ? null : byItem.get(itemId); }

    /**
     * Loose lookup for commands and requirement keys: the id, any counted alias ("COCOA_BEANS"),
     * the display name ("cocoa beans"), or a boss key ("BONZO", "F1").
     */
    public Coll resolve(String key) {
        if (key == null) return null;
        Coll c = byId.get(key);
        return c != null ? c : byKey.get(norm(key));
    }

    /** Resource collections (bosses excluded). */
    public int resourceCount() { return (int) byId.values().stream().filter(c -> !c.isBoss()).count(); }

    /** Tiers across resource collections (bosses excluded). */
    public int resourceTiers() { return totalTiers; }
}
